"""Publish source-aware descriptive findings; retain old summaries byte-for-byte."""
import build as C
import numpy as np,collections,json
O=C.O;R=C.R
def md(h,rr):return '\n'.join(['|'+'|'.join(h)+'|','|'+'|'.join(['---']*len(h))+'|']+['|'+'|'.join(map(str,r))+'|' for r in rr])
def main():
 v=C.read(O/'VERIFIED.json');assert v['passed'] and v['nearest_tie_robustness'];cov=C.rows(O/'COVERAGE.csv');lin=C.rows(O/'NODE_LINEAGE.csv');match=C.rows(O/'MATCH_COVERAGE.csv');patterns=C.rows(O/'ROBUST_PATTERN_COUNTS.csv');stable=C.rows(O/'PAIR_TIE_ROBUSTNESS.csv');features=C.rows(O/'PAIR_FEATURE_DETAILS.csv');ap=C.rows(O/'SOURCE_ROLE_AP_CONTRIBUTIONS_ADDITIVE.csv');lm={(r['key'],r['row']):r for r in lin};fm={(r['key'],r['route'],r['positive_row'],r['normal_row']):r for r in features};lookup={(r['protocol'],r['key'],r['route'],r['comparison'],r['positive_row']):r for r in stable}
 equality=[]
 for key in C.KEYS:
  z=dict(np.load(O/(key+'_features.npz')));ix={int(i):j for j,i in enumerate(z['rows'])}
  for link in C.rows(O/'FEATURE_NEAREST_LINKS.csv'):
   if link['key']==key and link['feature_equal']=='True':
    a,b=int(link['positive_row']),int(link['normal_row']);raw_equal=np.array_equal(z['raw'][ix[a]],z['raw'][ix[b]]);assert raw_equal;equality.append(dict(key=key,route=link['route'],positive_row=a,normal_row=b,raw39_equal=True,normalized39_equal=True))
 C.table('EXACT_FEATURE_EQUALITY_VERIFIED.csv',equality)
 def count(key,comp):return next(r for r in patterns if r['key']==key and r['comparison']==comp and r['protocol']=='last200' and r['radius_rms_z14']=='0.5')
 def close_stable(key,comp='GM-G0'):
  route='exposed_M_only' if key.endswith('train') else 'all_M';return [r for r in stable if r['key']==key and r['route']==route and r['comparison']==comp and r['protocol']=='last200' and float(r['rms_z14'])<=.5 and r['all_ties_coupled_seeds']=='3']
 def rolemean(key,comp,role):return float(np.mean([float(r['AP_contribution_delta']) for r in ap if r['protocol']=='last200' and r['key']==key and r['comparison']==comp and r['role']==role])) if any(r['key']==key and r['role']==role for r in ap) else 0.
 coverage_rows=[]
 for key in C.KEYS:
  p=next(r for r in cov if r['key']==key and r['side']=='positive');m=next(r for r in cov if r['key']==key and r['side']=='M');ex=[r for r in lin if r['key']==key and r['side']=='M' and int(r['M_exposure_200'])>0];coverage_rows.append([key,p['nodes'],p['pure_role'],p['mixed'],m['nodes'],f"{len(ex)} / {len({r['source'] for r in ex})}"])
 matchrows=[]
 for key in C.KEYS:
  route='exposed_M_only' if key.endswith('train') else 'all_M';r=next(r for r in match if r['key']==key and r['route']==route);matchrows.append([key,r['eligible_positive_roots'],r['matched'],r['feature_close'],r['feature_equal'],r['incoming_feature3_equal']])
 patrows=[]
 for key in C.KEYS:
  a,b=count(key,'GM-G0'),count(key,'GBM-GB');patrows.append([key,a['close'],f"{a['all_ties_coupled3']} / {a['sources']} / {a['source_gate_objects']}",f"{b['all_ties_coupled3']} / {b['sources']} / {b['source_gate_objects']}",a['chosen_actual_alarm_rank_cooccurrence_ge1'],a['chosen_actual_alarm_rank_cooccurrence3']])
 examples=[]
 for key,src,parent in [('trans_train','rs232t1000__a4trojan_s0_d1_s42','U0P0'),('trans_train','s35932t200__injalpha_d1_s42','TrojanAP2'),('trans_train','s15850t100__injdelta_d1_s42','TrojanDP2'),('orig_val','s38417t100__injbeta_d1_s42','TrojanBP2'),('orig_val','s38417t100__injzeta_d1_s42','TrojanFP3')]:
  r=next(r for r in close_stable(key) if r['positive_source']==src and r['positive_parents']==parent);f=fm[key,r['route'],r['positive_row'],r['normal_row']];examples.append([src+' / '+parent,r['flow_full']+' / '+r['gate'].removeprefix('gate_'),r['normal_source']+' / '+r['normal_parents'],f"{float(r['rms_z14']):.3f}",f"{float(r['normal_score_delta_mean']):+.4f}",f"{float(r['positive_score_delta_mean']):+.4f}",f"{float(r['positive_AP_contribution_delta_mean']):+.5f}"])
 # Fixed source/seed means, including absent role contributions as zero.
 ap_rows=[]
 for key in C.KEYS:
  for comp in ['GM-G0','GBM-GB']:ap_rows.append([key,comp,*[f'{rolemean(key,comp,role):+.5f}' for role in ['payload','output_hijack','trigger','payload_select','mixed_source']]])
 doc=['# 训练/验证角色血缘与M相似正常模式审计','', '2026-11-07。仅复用当前三种子五组的原选中与统一200步预测。0模型前向、0训练、0SAT，不改标签/可信掩码/图/原冻结角色表，不引入正例保护。测试预测未参与本轮匹配与分析。', '', '## 当前结论', '', '1. **血缘补齐后，可以把损失定位到具体制造来源，而不是按端口别名猜角色。**1220个正例、1014个M候选共2234节点的源对象/坐标全部核实；9个变换正例保留为混合来源。角色是审计附表，不将制造来源等同于每个中间门的实际安全必要性。', '2. **确有局部共同降分与正例排序损失，但不构成所有正例与正常逻辑的普遍冲突。**严格同宿主、完整实现流程（含keepcur/keepnone）、同门型，并检查所有最近距离并列节点后：末步200下GM−G0在近似匹配中，有5个变换训练节点（3个源网表、4个源门对象）及3个原始验证节点（2个源网表、3个源门对象）呈现三种子稳定共同降分/排名损失。主要是载荷；没有得到近似输出劫持后代同等强度的三种子稳定证据。', '3. **“共同降分”不能写成“每次消除一个误报就损害一个正例”。**上述配对中，M跨过报警阈值与正例排名受损可在部分种子共现，但没有任何一个近似配对在三个种子都同时发生。正常区域整体FPR下降是前轮结论，本轮定位的是风险模式，不是逐对因果证明。', '4. 39维根特征存在完全相同的正负例，但已匹配样本的三跳输入特征展开签名未相同；尚不能断言当前模型理论上必然无法区分。原始验证集损失较集中，变换验证集载荷AP贡献整体反而提升，不能概括为“载荷全部受损”。', '', '## 1. 角色血缘、制造用途与训练曝光', '', md(['范围','可信物理正例','纯制造角色','混合来源','M候选','实际曝光M节点 / 源网表'],coverage_rows), '', '原始训练/验证正例涉及18/5个独立源网表。变换后仍是这些源的多实现，不能当829或215个独立电路。M候选涉及训练29、验证7个正常源；实际监督仅训练原始93个节点/26源、变换173个节点/29源。其余M候选只能作未曝光区域评价，验证节点不参与监督。', '', '核查方式：当前fold源网表实例与引脚连接、provenance前缀及制造记录、每个实现的精确node_alignment，再与原训练alignment.json全局坐标独立比对。2234节点坐标无不一致。源网表中缺少PD、却实际存在HJ等历史清单差异单独记录，未修写旧清单。源角色不是仅凭目标节点Trojan/端口式名字分配。', '', md(['来源位置','审计含义','不能混为一谈的部分'],[['T*/TN*/TI*/TM*','制造触发网络的位置','正常M中的同名位置不是木马触发器'],['P数字','载荷/仿载荷链位置','XOR、XNOR或展开中间门不保证函数相同'],['S数字','载荷选择网络位置','不同于外部输出劫持'],['HJ','真实源中的输出劫持位置；正常源中仅仿劫持位置','不能给正常MUX赋木马安全角色'],['PD','已存在制造记录且端口类型匹配的末端负载','独立于真实源HJ，不视为一对一等价物'],['CtrlX的X数字、Buf','深XOR/XNOR链与末端辅助负载','s35932原生链实际使用XNOR，保留极性差别'],['多源/宿主混合后代','保留父门集合','不强行归入纯载荷/劫持；不改正标签']]), '', '每个源门的类型、原生连接、制造记录路径，及全部目标节点父门、直接端口核对、曝光次数均已保存。旧角色表未回填；这些新角色用于本轮补充解释。', '', '## 2. 对齐合同：不看预测挑配对', '', '主对齐先按同split、原始/变换侧、宿主、**完整流程后缀**及39维门型筛选，再以模型实际使用的14个非门型标准化/裁剪维度RMS距离找最近M。训练主分析只使用实际曝光M；验证使用已有M候选。另保留全M候选及已有source_node_pairs支持的制造对应路线。制造对应按源门/后代集合解释，近邻选择不产生功能等价或安全对应证明。', '', '记录所有最近距离并列对象；稳定结果进一步要求所有并列M都共同降分，防止任取一个有利对象。诊断近似门限为RMS≤0.5，并保存0.25/1.0敏感性结果；这些是离线审计门限，不是新训练参数。匹配先完成、再读取预测，未按正例得分/排名损失挑候选。', '', md(['范围','合格纯载荷/劫持后代','同流程/门型有匹配','RMS≤0.5','39维完全相同','三跳特征签名相同'],matchrows), '', '变换训练580个合格后代中，仅224个能与实际曝光M按完整流程同门型匹配，91个达到近似门限；其余356个不在此匹配解释范围，不能补猜。验证143个中65个匹配，28个近似。原始侧79/89和26/26分别匹配。keepcur/keepnone分开后，匹配覆盖比宽松流程检查下降，宽松中间结果仅留档，不用于最终结论。', '', '完整M候选路线中，原始训练13对、变换训练48对、变换验证8对根39维完全相同（原始验证0）；原始与实际归一化输入都相同，没有把裁剪造成的相同混为原始特征相同。但所有路线均未找到三跳特征签名相同配对。三跳核查使用当前保存的有向边与重复边次数，比较GIN入向消息可见的特征展开；门型二跳相同不等于三跳输入相同，签名也不是诱导子图同构或CEC证明。', '', '## 3. 哪些模式共同降分，并损害正例排名', '', '主要比较GM−G0（只替换M监督）与GBM−GB（B相同、再加入M），避免将B贡献算给M；GBM−G0、GB−G0完整结果同时保留。正例排名损失以同一可信物理负例集合上的AP逐正例贡献变化定位，并记录前方/并列负例数，不用报警阈值解释AP。', '', '下表均为末步200、RMS≤0.5：M降分需Δp<−0.001，正例AP贡献需Δ<−1e−6；“稳定”需三个seed均发生、且所有最近并列M都满足降分。此阈值用于排除过小波动，不构成严格数值误差界。', '', md(['范围','近似根数','GM−G0稳定：节点/源/源门对象','GBM−GB稳定：节点/源/源门对象','GM误报消除+排名损失至少1seed','三个seed均误报消除+排名损失'],patrows), '', '同一源门的多个展开节点、keepcur/keepnone重复实现分开保存，但源门对象计数去重。例如rs232 U0P0的两个实现是一个源门，不是两次独立制造。验证正常节点未参与训练，其变化是留出表现，不是直接监督效果。', '', '### 具体定位示例', '', '以下为GM−G0三种子的平均变化；最后一列是该正例对所在视图AP的贡献变化，不能直接相加当源宏AP损失。例子来自固定近邻表中已经满足上述稳定规则的对象。', '', md(['真实源 / 源门','完整流程 / 目标门型','近邻正常源 / 源门','RMS','正常Δp','正例Δp','视图AP贡献Δ'],examples), '', '- rs232的U0P0：真实与正常制造记录支持同源角色对应，两个abc保留流程分别匹配。目标均为INV型载荷展开后代，二跳门型上下文相同，根39维主要差别为PO距离（真实节点4，所选正常节点−1）；仍共同降分。不能说模型没有PO信息，而是已有距离信息没有确保保留排名。', '- s35932 alpha的AP2：真实载荷与正常载荷INV后代根特征非常接近，主要差别为寄存器边界输入侧距离；两者PO距离均−1。仅增加“PO是否可达”不能解决这类样本。', '- s15850 delta的DP2/DP0：与正常末端负载/仿触发网络的AND型展开后代根39维完全相同，但三跳特征上下文不同。DP0三种子AP贡献仍受损，说明用途不同的制造位置会落入相同局部摘要，不能按门型或P/T名称推断功能。', '- 原始验证beta的BP2、zeta的FP3：与正常AND/XOR仿载荷位置相近而共同降分。验证正例排名损失不是测试alpha特例；但不能因此认定全部近邻都是其训练梯度的直接来源。', '', '输出劫持来源的AP贡献确有损失，但其最明显的部分例子只有同门型、特征距离较远。严格近似及三种子规则下，本轮未定位到同等强度的“相似M→劫持排名损失”稳定模式，不将宽松匹配包装为已证实解释。', '', '### 选模与阈值边界', '', '固定200不是唯一时期结论：GM的5个近似变换训练稳定节点，没有任何一个同时在原选中检查点也满足全并列、三种子稳定规则；原始验证3个中2个可在两套检查点复现。GBM−GB对应变换训练3个中1个、原始验证3个中1个。局部病例有选模敏感性，不能宣称是跨轮次必然冲突。', '', '实际误报消除须由M的报警位1→0确认，不能只用分数降低替代。当前近似配对中，GM四个范围分别有6/2/4/5个根在至少一个seed出现“配对M消除误报且正例排名下降”；没有任何配对三个seed都如此。采用共同G0验证阈值后，GM上述共现数量相同，因而这些病例不只是重新校准阈值造成；但并不构成普遍一对一交换。', '', '## 4. 用补齐角色后完整解释AP，而不只挑受损案例', '', '以下为末步200的角色AP贡献差：各视图内角色贡献求和，缺失角色补0，再按实现→独立源→三个seed等权。各角色相加严格还原全体源宏AP差；不是只对具有某角色的视图取平均。', '', md(['范围','比较','载荷','劫持来源','触发','载荷选择','混合来源'],ap_rows), '', '原始验证GM的载荷/劫持贡献均值约−0.01869/−0.01555，说明这两类来源承担主要排序代价。原始训练触发和载荷均有代价。变换训练与验证的载荷贡献均值反而为正，尤其验证约+0.01458；劫持贡献略负。因此“某些载荷模式受损”与“总体载荷排序改善”可以同时成立，必须分源、分实现报告，不能只展示失败样本。', '', '## 5. 下一步建议', '', '本轮支持的解释是：**M监督使部分门型/局部摘要相似的模式共同降分，部分真实载荷的前列排名受到牵连；现有39维摘要与入向局部聚合未稳定利用用途/边界差异。**证据是病例、来源及配对对照的一致性，不是已证明的梯度因果，也不意味着必须给正例额外保护。', '', '下一步先做离线单因素诊断，优先复用本轮固定病例与正常制造对应：检查“末端悬空负载、有效输出劫持、D/SI等寄存器输入用途”能否由现有网表引脚和有向连接稳定区分，并核查这些信息是否已经进入模型输入。现有PO距离已经存在且某些正负例均不可达，不能只再加PO可达或门型。若这些边界/用途证据在训练与验证中可迁移，再冻结一个输入或消息方向的单因素对照合同，同时保留相同正负预算；不按测试alpha挑样、不改标签、不加正例保护。', '', '制造来源纯但节点安全作用不确定、混合来源、同完整流程无匹配、特征远的部分继续单列；不扩大解释范围，不把本轮审计直接升级为正式新训练结论。', '', '## 验证与证据', '', f"独立检查通过：2234节点坐标、{v['matched_link_checks']}个匹配的特征距离/侧别/宿主/完整流程、{v['nearest_minimum_and_tie_checks']}个最小距离与并列候选、{v['three_seed_flag_checks']}组三种子标志、{v['AP_source_role_additivity_checks']}次角色AP可加性、{v['AP_view_reproductions']}次历史视图AP复算。模型、标签、特征、边与120份既有预测的保护哈希保持。", '', '`_p0pilot/control_role_pattern_20261107/`：`NODE_LINEAGE.csv`、`SOURCE_GATE_ROLES.csv`、`DIRECT_PORT_CHECKS.csv`、`PROVENANCE_DISCREPANCIES.csv`、`COVERAGE.csv`；`*_features.npz`、`LOCAL_DESCRIPTORS.csv`、`FEATURE_NEAREST_LINKS.csv`、`MATCH_COVERAGE.csv`；`NODE_PREDICTIONS.csv`、`NODE_DELTAS.csv`、`PAIR_FEATURE_DETAILS.csv`、`PAIR_PREDICTION_CHANGES.csv`、`PAIR_OBJECT_THEN_SOURCE.csv`、`PAIR_TIE_ROBUSTNESS.csv`、`ROBUST_PATTERN_COUNTS.csv`；`SOURCE_ROLE_AP_CONTRIBUTIONS_ADDITIVE.csv`、`VERIFIED.json`。中间角色/宽松流程版本另目录留档，以本报告对应的最终表为准。','']
 report=R/'10.15/00_说明/正常对照_训练验证角色血缘与M相似模式审计_20261107.md';assert not report.exists();text='\n'.join(doc)
 # Ensure all final Markdown tables have the declared column count.
 expected=None
 for line in text.splitlines():
  if line.startswith('|'):
   n=len(line.split('|'));assert expected in [None,n],line;expected=n
